"""GN field construction for a common cut through two straight member rays.

These classes describe node expressions, not prepared surface coordinates.
The complete source paths and native Bundle guards must certify the straight
member domain before the network publishes this branch.
"""
from dataclasses import dataclass
from .backend_runtime import choose, rm


def add(a,b):return [x+y for x,y in zip(a,b)]
def sub(a,b):return [x-y for x,y in zip(a,b)]
def scale(a,s):return [v*s for v in a]
def dot(a,b):return sum(x*y for x,y in zip(a,b))
def right(t):return [t[1],-t[0]]
def select(g,test,a,b):return [choose(g,test,x,y) for x,y in zip(a,b)]
def unit(g,a):return scale(a,g.math('DIVIDE',1.,g.math('SQRT',dot(a,a))))


def cut(origin,tangent,axis,station):
    """Intersect one physical offset line with axis.dot(X) = station."""
    return add(origin,scale(tangent,(station-dot(origin,axis))/dot(tangent,axis)))


@dataclass
class MemberRay:
    start: object
    end: object
    tangent: object
    width: object
    offset: object

    def edge(self,axis,side,station=0.):
        origin=add(self.start,scale(right(self.tangent),self.offset+side*self.width*.5))
        return cut(origin,self.tangent,axis,station)


def arm(g,divided,first,second,axis_delta=None):
    a,b=MemberRay(*first),MemberRay(*second)
    delta=sub(a.tangent,b.tangent)
    active=divided*g.math('GREATER_THAN',dot(delta,delta),1e-10)
    displacement=sub(add(a.end,b.end),add(a.start,b.start))
    if axis_delta is not None:
        displacement=select(g,g.math('GREATER_THAN',dot(axis_delta,axis_delta),1e-10),axis_delta,displacement)
    axis=select(g,active,unit(g,displacement),a.tangent)
    normal=right(axis)
    ca,cb=a.edge(axis,0.),b.edge(axis,0.)
    a_left=g.math('LESS_THAN',dot(ca,normal),dot(cb,normal))
    left=select(g,a_left,a.edge(axis,-1.),b.edge(axis,-1.))
    left_inner=select(g,a_left,a.edge(axis,1.),b.edge(axis,1.))
    right_edge=select(g,a_left,b.edge(axis,1.),a.edge(axis,1.))
    right_inner=select(g,a_left,b.edge(axis,-1.),a.edge(axis,-1.))
    lt=select(g,a_left,a.tangent,b.tangent)
    rt=select(g,a_left,b.tangent,a.tangent)
    forward=g.math('GREATER_THAN',dot(a.tangent,axis),.5)*g.math('GREATER_THAN',dot(b.tangent,axis),.5)
    return dict(active=active,axis=axis,normal=normal,left_origin=left,right_origin=right_edge,
        left_inner=left_inner,right_inner=right_inner,left_direction=lt,right_direction=rt,
        forward=forward,outer_station=g.math('MINIMUM',dot(a.end,axis),dot(b.end,axis)),
        minimum_station=g.math('MAXIMUM',0.,g.math('MAXIMUM',dot(a.start,axis),dot(b.start,axis))))


def read(g,arms,name,index,kind='FLOAT'):
    value=rm.read(g,arms,name,index,kind)
    return g.separate(value)[:2] if kind=='FLOAT_VECTOR' else value


def edge_at(g,arms,index,side,station,*,inner=False):
    origin=read(g,arms,side+('_inner' if inner else '_origin'),index,'FLOAT_VECTOR')
    tangent=read(g,arms,side+'_direction',index,'FLOAT_VECTOR')
    axis=read(g,arms,'tangent',index,'FLOAT_VECTOR')
    return cut(origin,tangent,axis,station)


def section(g,arms,index,station):
    normal=read(g,arms,'right',index,'FLOAT_VECTOR')
    left=edge_at(g,arms,index,'left',station)
    right_edge=edge_at(g,arms,index,'right',station)
    li=edge_at(g,arms,index,'left',station,inner=True)
    ri=edge_at(g,arms,index,'right',station,inner=True)
    lo,hi,il,ir=[dot(p,normal) for p in (left,right_edge,li,ri)]
    width=hi-lo;gap=ir-il
    center=(lo+hi)*.5;peak=(il+ir)*.5
    half_left,half_right=peak-lo,hi-peak
    return dict(origin=scale(normal,center),width=width,plateau_fraction=gap/width,
        profile_shift=peak-center,left_half_width=half_left,right_half_width=half_right,
        left_plateau_fraction=gap/(2.*half_left),right_plateau_fraction=gap/(2.*half_right),
        gap=gap)
